const pruneDocSnapshots = `-- name: PruneDocSnapshots :exec
DELETE FROM doc_snapshots d
WHERE d.scope = $1 AND d.kind = $2 AND d.cluster_id IS NOT DISTINCT FROM $3::uuid
  AND d.id < (SELECT coalesce(min(k.id), 0) FROM (
      SELECT s.id FROM doc_snapshots s
      WHERE s.scope = $1 AND s.kind = $2 AND s.cluster_id IS NOT DISTINCT FROM $3::uuid
      ORDER BY s.id DESC
      LIMIT $4) k)
`

type PruneDocSnapshotsParams struct {
	Scope     string
	Kind      string
	ClusterID *uuid.UUID
	Keep      int32
}

// Houdt de nieuwste @keep versies van één document.
func (q *Queries) PruneDocSnapshots(ctx context.Context, arg PruneDocSnapshotsParams) error {
	_, err := q.db.Exec(ctx, pruneDocSnapshots,
		arg.Scope,
		arg.Kind,
		arg.ClusterID,
		arg.Keep,
	)
	return err
}

