const updateDocsTarget = `-- name: UpdateDocsTarget :one
UPDATE docs_targets SET
    api_url = $1, owner = $2, name = $3, branch = $4, path = $5,
    token_enc = $6, key_id = $7, enabled = $8,
    last_commit_sha = CASE WHEN $9::boolean THEN '' ELSE last_commit_sha END,
    last_commit_url = CASE WHEN $9::boolean THEN '' ELSE last_commit_url END,
    last_commit_files = CASE WHEN $9::boolean THEN 0 ELSE last_commit_files END,
    last_published_at = CASE WHEN $9::boolean THEN NULL ELSE last_published_at END,
    last_checked_at = CASE WHEN $9::boolean THEN NULL ELSE last_checked_at END,
    last_error = CASE WHEN $9::boolean THEN '' ELSE last_error END,
    updated_at = now()
WHERE id = $10
RETURNING id, api_url, owner, name, branch, path, token_enc, key_id, enabled, last_commit_sha, last_commit_url, last_commit_files, last_published_at, last_checked_at, last_attempt_at, last_error, created_at, updated_at
`

type UpdateDocsTargetParams struct {
	ApiUrl   string
	Owner    string
	Name     string
	Branch   string
	Path     string
	TokenEnc []byte
	KeyID    string
	Enabled  bool
	Reset    bool
	ID       uuid.UUID
}

// Een andere repository, branch of map begint opnieuw: de laatste commit
// en fout horen bij de oude bestemming.
func (q *Queries) UpdateDocsTarget(ctx context.Context, arg UpdateDocsTargetParams) (DocsTarget, error) {
	row := q.db.QueryRow(ctx, updateDocsTarget,
		arg.ApiUrl,
		arg.Owner,
		arg.Name,
		arg.Branch,
		arg.Path,
		arg.TokenEnc,
		arg.KeyID,
		arg.Enabled,
		arg.Reset,
		arg.ID,
	)
	var i DocsTarget
	err := row.Scan(
		&i.ID,
		&i.ApiUrl,
		&i.Owner,
		&i.Name,
		&i.Branch,
		&i.Path,
		&i.TokenEnc,
		&i.KeyID,
		&i.Enabled,
		&i.LastCommitSha,
		&i.LastCommitUrl,
		&i.LastCommitFiles,
		&i.LastPublishedAt,
		&i.LastCheckedAt,
		&i.LastAttemptAt,
		&i.LastError,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertDocSummary = `-- name: UpsertDocSummary :exec
INSERT INTO doc_summaries (cluster_id, text, model, created_by, created_at, conversation_id)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (cluster_id) DO UPDATE
SET text = excluded.text, model = excluded.model, created_by = excluded.created_by, created_at = excluded.created_at,
    conversation_id = excluded.conversation_id
`

type UpsertDocSummaryParams struct {
	ClusterID      uuid.UUID
	Text           string
	Model          string
	CreatedBy      *uuid.UUID
	CreatedAt      time.Time
	ConversationID *uuid.UUID
}

func (q *Queries) UpsertDocSummary(ctx context.Context, arg UpsertDocSummaryParams) error {
	_, err := q.db.Exec(ctx, upsertDocSummary,
		arg.ClusterID,
		arg.Text,
		arg.Model,
		arg.CreatedBy,
		arg.CreatedAt,
		arg.ConversationID,
	)
	return err
}
